// V34: fixed-capacity feedback only. All arithmetic (including three scalar
// feedback outputs) is captured from MLX. No new shader or ICB is created.
struct InputRange {uintptr_t addr,buffer;size_t size,offset;uint32_t role;std::string name;};
struct FeedbackLink {uintptr_t input,output;size_t size;};
struct StageRange {uintptr_t addr;size_t size,offset;};
struct StepTiming {unsigned request,step;uint64_t graphEncode,feedbackEncode,encode,commit,wait,total;double gpuStart,gpuEnd;bool valid;};
