static Feedback&F(){static Feedback f;return f;}
static const InputRange*input(uintptr_t a,size_t n=0){for(auto&x:F().inputs)if(x.addr==a&&(!n||x.size==n))return &x;return nullptr;}
static const Output*output(uintptr_t a,size_t n=0){for(auto&x:S().outputs)if(x.addr==a&&(!n||x.size==n))return &x;return nullptr;}
static const StageRange*stage(uintptr_t a,size_t n=0){for(auto&x:F().stages)if(x.addr==a&&(!n||x.size==n))return &x;return nullptr;}
static const PingPair*pingOutput(uintptr_t a,size_t n=0){for(auto&p:PP().pairs)if(p.eligible&&p.output==a&&(!n||p.size==n))return &p;return nullptr;}
static unsigned eligiblePings(){unsigned n=0;for(auto&p:PP().pairs)n+=p.eligible;return n;}
static const unsigned char*resultBytes(uintptr_t a,size_t n){if(auto*p=pingOutput(a,n)){auto&b=S().buffers.at(PP().bank?p->b:p->a);return (const unsigned char*)S().arena.contents+b.arena;}if(auto*x=stage(a,n))return (const unsigned char*)F().stage.contents+x->offset;return nullptr;}
