static size_t arenaInput(const InputRange&x){return S().buffers.at(x.buffer).arena+x.offset;}
static size_t arenaOutput(const Output&x){return S().buffers.at(x.buffer).arena+x.offset;}
static bool overlap(size_t a,size_t an,size_t b,size_t bn){return a<b+bn&&b<a+an;}
extern "C" int v34_register_input(uint64_t addr,uint64_t n,uint32_t role,const char*name){
 std::lock_guard<std::recursive_mutex>lock(S().lock);
 if(!S().built||F().sealed||!S().error.empty()||!addr||!n||role>3||input(addr)){fail("invalid/duplicate/late feedback input");return 1;}
 for(auto&kv:S().buffers){auto&b=kv.second;uintptr_t base=(uintptr_t)b.b.contents;
  if(b.used&&!b.zero&&!b.pinCandidate&&base&&addr>=base&&n<=b.b.length&&addr-base<=b.b.length-n){
   bool read=false;for(auto start:b.readStarts)if(start>=base&&start<addr+n)read=true;
   if(!read){fail("input allocation has no captured read binding for its range");return 1;}
   if((addr-base)%4||n%4||(role&&n!=4)){fail("input range not 4-byte aligned or scalar not int32 width");return 1;}
   F().inputs.push_back({(uintptr_t)addr,kv.first,(size_t)n,(size_t)(addr-base),role,name?name:"input"});return 0;
  }
 }
 fail("input address is not a captured mutable-arena read allocation/range");return 1;
}
extern "C" int v34_link(uint64_t in,uint64_t out,uint64_t n){
 std::lock_guard<std::recursive_mutex>lock(S().lock);
 if(F().sealed||!S().error.empty()||!input(in,n)||!output(out,n)){fail("feedback link requires exact registered input/output ranges");return 1;}
 for(auto&x:F().links)if(x.input==in||x.output==out){fail("duplicate feedback input/output link");return 1;}
 F().links.push_back({(uintptr_t)in,(uintptr_t)out,(size_t)n});return 0;
}
